from pathlib import Path
import json
root=Path(__file__).parent/'dist'
nav=[('','首页'),('how-it-works','工作原理'),('data-factory','数据与知识工厂'),('research','实践与研究'),('contact','关于与合作')]
def visual():return '''<div class="visual" aria-label="双闭环概念图：运行环交付任务，改进环经过评测与审批后更新版本"><div class="cap"><span class="micro">HARNESS / SYSTEM MAP</span><span class="micro">概念演示</span></div><div class="orbit"></div><div class="orbit two"></div><div class="hub">业务专属<br>Harness<span>CONTROLLED EVOLUTION</span></div><span class="node n1">01 业务任务 ↗</span><span class="node n2">运行 · 执行与交付</span><span class="node n3">改进 · 反馈与评测</span><span class="node n4">发布闸门 ✓</span><div class="visual-foot"><span>RUN → EVALUATE → EVOLVE</span><span>HUMAN IN CONTROL</span></div></div>'''
def cta():return '''<div class="wrap band"><div><span class="eyebrow">START WITH A REAL TASK</span><h2>从一个真实业务问题开始。</h2><p class="lead">先定义什么是好结果，再讨论如何让 AI 做到。</p></div><a class="btn" href="/contact/">讨论你的业务场景 <span>↗</span></a></div>'''
pages={}
pages['']=('为业务构建持续进化的 AI Harness','''<div class="wrap"><div class="hero"><div><span class="eyebrow">BUSINESS-ADAPTIVE AI SYSTEMS</span><h1>让 AI 适配业务。<br><em>让改进形成闭环。</em></h1><p class="lead">从业务任务、数据和质量标准出发，构建可评估、可控制、可持续优化的 AI Harness。</p><div class="actions"><a class="btn" href="/contact/">讨论你的业务场景 <span>↗</span></a><a class="textlink" href="/how-it-works/">了解工作原理 ↗</a></div><p class="micro" style="margin-top:35px">BUILT AROUND YOUR WORK. NOT THE OTHER WAY AROUND.</p></div>'''+visual()+'''</div><div class="strip"><div><b>业务适配</b>从任务与验收标准出发</div><div><b>评测驱动</b>用证据，而不是直觉改进</div><div><b>边界可控</b>保留人工判断与发布闸门</div></div></div><section class="wrap"><div class="sectionhead"><div><span class="eyebrow">BEYOND A PROMPT</span><h2>模型很强。<br>业务需要的不止是模型。</h2></div><p>模型之外，信息、工具、规则与评测共同决定 AI 能否把事情做好。</p></div><div class="cards"><div class="card"><span class="num">01 / CONTEXT</span><h3>换一批数据，结果就不稳定</h3><p>让数据来源、任务上下文与工具调用成为系统的一部分，而非临时拼接。</p></div><div class="card"><span class="num">02 / QUALITY</span><h3>流程能跑，质量却难验收</h3><p>将“做得好”转化为明确的业务约束、测试样本与复核标准。</p></div><div class="card"><span class="num">03 / FEEDBACK</span><h3>同样的错误，反复人工修正</h3><p>把失败与反馈沉淀为候选改进，并在独立评测后决定是否采用。</p></div></div></section><section class="light"><div class="wrap split"><div><span class="eyebrow">TWO LOOPS. ONE SYSTEM.</span><h2>一个环交付任务。<br>一个环，让系统进步。</h2><p class="lead">Harness 是围绕模型的执行系统：它决定 AI 使用什么信息和工具、怎样完成任务，以及如何判断结果是否合格。</p><div class="flow"><span>运行环</span><i>→</i><span>任务 / 执行 / 检查</span></div><div class="flow"><span>改进环</span><i>→</i><span>反馈 / 评测 / 审批</span></div><div class="actions"><a class="textlink" href="/how-it-works/">查看双闭环架构 ↗</a></div></div><div class="paperdemo"><div class="micro" style="color:#68775b">DESIGN PRINCIPLE / 001</div><h3>每一次改进，都经过评估。<br>每一次发布，都有边界。</h3><div class="line"><span>候选版本</span><span>在隔离环境中试验</span></div><div class="line"><span>独立评测</span><span>检查改善，也检查退化</span></div><div class="line"><span>发布决策</span><span>按约定规则审批</span></div><div class="line"><span>上线之后</span><span>保留监测与回退路径</span></div></div></div></section><section class="wrap split"><div><span class="eyebrow">FIRST FOCUS / DATA & KNOWLEDGE</span><h2>从复杂资料，<br>到可检验的数据资产。</h2><p class="lead">数据与知识工厂是我们的首个重点方向。将抽取、证据定位、质量检查与人工反馈连接成可追溯的工作流。</p><div class="actions"><a class="btn secondary" href="/data-factory/">探索合成任务演示 ↗</a></div></div><div class="box"><div class="demohead"><span class="micro">DOCUMENT → STRUCTURED RECORD</span><span class="tag">合成示例</span></div><div class="result-row"><b>输入</b><span>采购规格说明 / 文档片段</span></div><div class="result-row"><b>处理</b><span>字段提取 → 来源关联 → 规则检查</span></div><div class="result-row"><b>输出</b><span class="good">可追溯记录 + 待复核问题</span></div><p>不把缺失信息猜成答案，不把演示结果当成客户成果。</p></div></section>''')
pages['how-it-works']=('工作原理','''<div class="wrap subhero"><span class="eyebrow">HOW IT WORKS</span><h1>不是一个更长的提示词。<br>是一套围绕业务的执行系统。</h1><p class="lead">模型负责推理，Harness 组织上下文、工具、约束与反馈。我们从业务验收标准出发，设计每一个环节。</p></div><section class="wrap two"><div class="box"><span class="eyebrow">01 / RUN LOOP</span><h2>在边界内，完成任务。</h2><p>业务输入 → 上下文与工具 → 执行 → 质量检查 → 交付或人工复核。</p><ul><li>连接授权数据与工具，不默认获得所有权限。</li><li>保留来源、步骤与异常，允许在不确定时停止。</li><li>将无法可靠判断的结果送交人工，而非强行给出结论。</li></ul></div><div class="box"><span class="eyebrow">02 / EVOLUTION LOOP</span><h2>用反馈，验证下一步。</h2><p>失败与反馈 → 候选改进 → 独立评测 → 发布决策 → 监测。</p><ul><li>在限定范围内调整提示、工具配置或工作流。</li><li>用独立样本检查改善与回归，不只看优化样本。</li><li>通过人工审批或预先约定的闸门，才进入正式版本。</li></ul></div></section><section class="light"><div class="wrap"><span class="eyebrow">SYSTEM LAYERS</span><h2>为业务补齐四个层次。</h2><div class="flow"><span>模型 · 推理能力</span><i>→</i><span>信息与工具 · 任务资源</span><i>→</i><span>流程与权限 · 执行边界</span><i>→</i><span>评测与反馈 · 改进依据</span></div><p class="lead">这是一种系统设计方法，不意味着所有业务都能自动优化，也不等于持续训练模型权重。</p></div></section><section class="wrap"><span class="eyebrow">WHAT WE DESIGN WITH YOU</span><h2>可交付的，不只有一次回答。</h2><div class="steps"><div class="step"><h3>业务专属 Harness</h3><p>任务定义、数据与工具接入方案、权限及人工节点。</p></div><div class="step"><h3>可执行的质量标准</h3><p>代表性样本、评测维度、失败分类与回归检查方法。</p></div><div class="step"><h3>受控的版本改进机制</h3><p>候选与基线对比、独立验证、发布边界和回退方案。</p></div><div class="step"><h3>可追溯的运行记录</h3><p>将来源、版本、执行步骤与人工决策纳入试点设计。</p></div></div><p class="notice">以上是服务设计与试点交付方向。具体能力、接入方式和交付范围以场景评估与合作约定为准。</p></section>''')
pages['data-factory']=('数据与知识工厂','''<div class="wrap subhero"><span class="eyebrow">DATA & KNOWLEDGE FACTORY</span><h1>把资料变成数据。<br>把修正变成改进的依据。</h1><p class="lead">不只关注提取了多少字段，更关注它来自哪里、能否通过检查，以及下一版怎样避免同样的错误。</p></div><section class="wrap" style="padding-top:10px"><p class="notice">交互概念演示：以下资料、版本与检查结果全部为合成示例，非客户数据、非模型实时运行，也不代表实际质量提升。</p><div class="tabs" role="tablist" aria-label="演示步骤"><button role="tab" aria-selected="true" data-stage="0">01 原始提取</button><button role="tab" aria-selected="false" data-stage="1">02 质量检查</button><button role="tab" aria-selected="false" data-stage="2">03 候选改进</button></div><div class="two"><div class="box"><div class="demohead"><h3>输入资料</h3><span class="tag">SYNTHETIC DOC-001</span></div><p class="source">[L1] 项目：样例设备采购<br>[L2] 订购数量为 20 台。<br>[L3] 单价为人民币 1,200 元，含税。<br>[L4] 交货时间为订单确认后 15 个工作日。<br>[L5] 运费由双方另行确认。</p><p class="micro">SOURCE PRESERVED · EVIDENCE LINKED</p></div><div class="box" id="demo-output" aria-live="polite"></div></div><div class="box" style="margin-top:24px"><span class="eyebrow">RELEASE GATE</span><h3>候选改进，不等于已经发布。</h3><p>该示例只展示一个已知错误如何进入改进流程。是否采用候选版本，还需要独立样本、回归检查和约定的发布决策。没有验证的数据，保持未知。</p></div></section>''')
pages['research']=('实践与研究','''<div class="wrap subhero"><span class="eyebrow">FIELD NOTES</span><h1>让方法可讨论。<br>让改进有证据。</h1><p class="lead">这里记录我们的系统设计思路与演示方法。它们不是客户案例，也不是已完成的性能评测报告。</p></div><section class="wrap" style="padding-top:10px"><article class="article"><small>NOTE 01</small><div><h3>为什么要把运行环和改进环分开？</h3><p>完成业务任务与修改系统配置，是两种风险不同的动作。将它们分开，才能明确谁能改、改什么、何时生效。</p><details><summary>展开设计笔记</summary><p>运行环使用固定版本执行任务；改进环收集问题并提出候选。候选必须经过独立评测和发布闸门，不能凭一次成功自动改写生产流程。发布之后仍需监测，并保留回退版本。</p></details></div><span>↗</span></article><article class="article"><small>NOTE 02</small><div><h3>数据工厂：先建立失败分类，再谈优化</h3><p>缺失信息、错误推断、单位转换和来源丢失，需要不同的检查方法。</p><details><summary>展开设计笔记</summary><p>对每个字段分别记录来源位置、提取值和验证状态。缺失不等于否定，不确定不等于错误。先确认失败类型，再决定通过规则、上下文补充、工具调整还是人工判断解决。</p></details></div><span>↗</span></article><article class="article"><small>NOTE 03</small><div><h3>从候选版本到业务证据</h3><p>优化样本上的进步，不一定能迁移到下一批数据。回归检查和独立测试同样重要。</p><details><summary>展开设计笔记</summary><p>在试点中，我们建议分离开发样本与独立评测样本，并同时关注质量、成本、时延和人工复核负担。基线、样本分布与评测边界未建立前，不报告提升百分比。</p></details></div><span>↗</span></article><div class="notice">技术参考：<a class="textlink" href="https://github.com/rsi-gear/gear" target="_blank" rel="noopener noreferrer">GEAR 开源项目 ↗</a>。引用用于说明研究方向，不代表合作、背书或已完成的产品集成。</div></section>''')
pages['contact']=('关于与合作','''<div class="wrap subhero"><span class="eyebrow">LET’S BUILD A USEFUL LOOP</span><h1>不从“用哪个模型”开始。<br>从“什么结果算合格”开始。</h1><p class="lead">HarnessLoop 聚焦业务适配的 AI 执行系统。我们希望与数据和知识密集型业务一起，把一个具体任务做成可检查、可改进的工作流。</p></div><section class="wrap two" style="padding-top:10px"><div><h2>先定义一个小而清晰的试点。</h2><div class="steps"><div class="step"><h3>场景诊断</h3><p>明确任务、瓶颈与风险边界。</p></div><div class="step"><h3>样本与基线</h3><p>用获授权、脱敏的代表性样本确定验收方式。</p></div><div class="step"><h3>定制试点</h3><p>构建最小工作流，核验质量与人工成本。</p></div><div class="step"><h3>接入与持续优化</h3><p>按验证结果决定范围、发布与后续迭代。</p></div></div></div><div class="box"><h3>整理你的场景简报</h3><p>本页仅在浏览器中生成简报，不发送、不保存。正式联系入口将在确认后接入。</p><form class="form" id="brief-form"><label>希望 AI 完成什么任务？<input name="task" required maxlength="200" placeholder="例如：从供应商资料提取采购字段"></label><label>当前最难的部分<textarea name="pain" required maxlength="800" placeholder="例如：格式不统一，人工核对重复"></textarea></label><label>什么结果才算合格？<textarea name="criteria" required maxlength="800" placeholder="例如：关键字段必须能定位到来源"></textarea></label><button class="btn" type="submit">生成本地简报 ↗</button></form><p class="micro">请勿填写患者信息、客户个人信息、密码或商业机密。</p><div id="brief-panel" class="hidden"><h3>简报已在本地生成，尚未发送</h3><pre class="brief" id="brief"></pre><button class="btn secondary" id="copy-brief" type="button">复制简报</button><p id="copy-status" role="status"></p></div></div></section>''')
for slug,(title,body) in pages.items():
 links=''.join(f'<a href="/{s+"/" if s else ""}"'+(' aria-current="page"' if s==slug else '')+f'>{label}</a>' for s,label in nav)
 html=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | HarnessLoop</title><meta name="description" content="HarnessLoop 为数据与知识密集型业务设计专属 AI Harness，通过评测驱动的反馈循环持续改进。"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#101713"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/app.js"></script></head><body><a class="skip" href="#main">跳转到主要内容</a><header><div class="wrap nav"><a class="brand" href="/" aria-label="HarnessLoop 首页"><span class="logo" aria-hidden="true"></span>HarnessLoop</a><nav class="navlinks" id="navigation" aria-label="主导航">{links}</nav><a class="navcta" href="/contact/">一起构建 ↗</a><button class="menu" aria-label="展开导航" aria-expanded="false" aria-controls="navigation">菜单</button></div></header><main id="main">{body}{cta() if slug!='contact' else ''}</main><footer><div class="wrap foot"><div>© 2026 HarnessLoop <span style="margin-left:15px">Business-adaptive AI systems.</span></div><div>开发预览 · 不收集表单数据 · <a href="/privacy/">隐私说明</a></div></div></footer></body></html>'''
 path=root/slug/'index.html';path.parent.mkdir(parents=True,exist_ok=True);path.write_text(html)
(root/'privacy').mkdir(exist_ok=True)
(root/'privacy/index.html').write_text('''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>隐私说明 | HarnessLoop</title><link rel="stylesheet" href="/assets/style.css"><main class="wrap subhero"><a class="textlink" href="/contact/">← 返回关于与合作</a><h1>开发预览隐私说明</h1><p class="lead">本地简报工具只在当前页面内处理你输入的内容，不将表单内容发送给服务器，不使用 Cookie 或本地存储保存简报；刷新后输入不会由本工具保留。本站未接入分析追踪、第三方字体或表单服务。预览服务器可能产生访问请求日志。</p><p class="lead">请勿填写个人敏感资料、病历、凭据或商业机密。正式上线前，需按实际运营主体、托管服务和联系渠道完善隐私政策。</p></main></html>''')
(root/'assets/favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="14" fill="#101713"/><circle cx="32" cy="32" r="20" stroke="#cbf37a" stroke-width="4" fill="none"/><path d="M32 12V32H52" fill="none" stroke="#cbf37a" stroke-width="4"/></svg>')
(root/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
